import { mkdir, readFile, writeFile } from "node:fs/promises";

const root = new URL("../", import.meta.url);
const moduleFiles = [
  "js/config.js",
  "js/languages/kiosk.js",
  "js/services/data-loader.js",
  "js/services/history.js",
  "js/services/translator.js",
  "js/app.js"
];

function toClassic(source) {
  return source
    .replace(/^import .*;\r?\n/gm, "")
    .replace(/^export\s+/gm, "");
}

await mkdir(new URL("js/generated/", root), { recursive: true });
await mkdir(new URL("data/generated/", root), { recursive: true });

const modules = [];
for (const file of moduleFiles) {
  modules.push(`// Source: ${file}\n${toClassic(await readFile(new URL(file, root), "utf8"))}`);
}
const bundle = `/* Generated by scripts/build-file-bundle.mjs. Do not edit directly. */\n(() => {\n${modules.join("\n\n")}\n})();\n`;
await writeFile(new URL("js/generated/app.bundle.js", root), bundle);

for (const [code, file] of [["id", "indonesia.json"], ["vi", "vietnam.json"]]) {
  const data = JSON.parse(await readFile(new URL(`data/${file}`, root), "utf8"));
  await writeFile(new URL(`data/generated/${code}.js`, root), `window.HELLOWORLD_DATA=${JSON.stringify(data)};\n`);
}

console.log("file:// 호환 번들 생성 완료");
